pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        // Assume valid contract_address (non-zero, not this contract)
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));

        // Ensure arrays have same length and are non-empty
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        // Deploy a mock contract that will fail on the last call
        FailOnLastCall mock = new FailOnLastCall();
        vm.assume(contract_address != address(mock)); // avoid address conflict

        // Make the contract_address be the mock so we can control failures
        // But we need to test with any contract_address; we can deploy mock and set contract_address = address(mock)
        // To keep the fuzz general, we override contract_address to point to a failing mock
        contract_address = address(mock);

        bool result = c.transfer(contract_address, tos, vs);

        // The reference returns false because at least one call fails, but the mutant returns true
        assertTrue(result == false);
    }
}

contract FailOnLastCall {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        // Always fails (returns false) on the first call; we use multiple calls to trigger failure
        // For simplicity, we always fail
        return false;
    }
}

