pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        // Constrain inputs to allow valid calls
        vm.assume(contract_address != address(0) && contract_address != address(c));
        vm.assume(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        // Ensure at least one call will fail (e.g., using a contract that will revert on transferFrom)
        // Deploy a simple contract that reverts on any call
        address failContract = address(new FailContract());
        // Override contract_address to our failContract
        bool success;
        (success, ) = address(c).call(abi.encodeWithSignature("transfer(address,address[],uint256[])", failContract, tos, vs));
        assertTrue(success);
    }
}

contract FailContract {
    fallback() external payable {
        revert("fail");
    }
}

