pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        // restrict inputs so the reference does not revert
        vm.assume(contract_address != address(0) && contract_address != address(c));
        vm.assume(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0) && tos[i] != address(c));
        }

        bool returned = c.transfer(contract_address, tos, vs);
        // The reference returns true if and only if all internal calls succeed.
        // To generalize, we can check that the returned value equals the success of calling the last internal call.
        // We simulate the last low-level call to check its result.
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        (bool lastSuccess, ) = contract_address.call(abi.encodeWithSelector(id, address(this), tos[tos.length-1], vs[vs.length-1]));
        // The buggy version always returns true regardless of internal call success.
        // So we assert that the returned value equals the success of the last call.
        assertTrue(returned == lastSuccess);
    }
}

