contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory tos, uint256[] memory vs) public {
        // Restrict to valid inputs for the reference: tos.length > 0, vs.length > 0, lengths equal
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        // Ensure no address in tos is address(0) or address(this) to avoid revert in reference (modifier disallows address(this) for contract_address only)
